// Une cada consulta con su ficha de cliente (por email).
// Si Google Sheets falló, sigue sin ficha y lo informa al agente.
const EQUIPO = {
  ventas: 'paula.delgado345+ventas@gmail.com',
  calidad: 'paula.delgado345+calidad@gmail.com',
};
const consultas = $('¿Consulta válida?').all().map(i => i.json);
let clientes = [];
let fichaDisponible = true;
try {
  const filas = $('Leer clientes').all().map(i => i.json);
  if (filas.some(f => f.error)) fichaDisponible = false;
  clientes = filas.filter(f => f.email);
} catch (e) {
  fichaDisponible = false;
}
return consultas.map(c => {
  const cli = clientes.find(x => String(x.email).trim().toLowerCase() === c.email);
  return { json: {
    ...c,
    cliente_encontrado: Boolean(cli),
    ficha_disponible: fichaDisponible,
    razon_social: cli?.razon_social ?? 'No registrado',
    tipo_cliente: cli?.tipo_cliente ?? '',
    comuna: cli?.comuna ?? '',
    estado_credito: cli?.estado_credito ?? 'Desconocido',
    ejecutivo: cli?.ejecutivo ?? 'Equipo de ventas',
    email_ventas: cli?.email_ejecutivo || EQUIPO.ventas,
    email_calidad: EQUIPO.calidad,
  }};
});

