// Red de seguridad sobre la decisión del agente, antes de tocar datos reales.
const ctx = $('Cruzar consulta con cliente').item.json;
const out = $json.output || {};
const ACCIONES = ['responder', 'pedir_informacion', 'derivar_ventas', 'escalar_calidad'];
const problemas = [];
let accion = out.accion;

if (!ACCIONES.includes(accion)) { problemas.push('accion_invalida'); accion = 'derivar_ventas'; }
const respuesta = String(out.respuesta_cliente || '').trim();
if (respuesta.length < 30) problemas.push('respuesta_vacia');
const confianza = Number(out.confianza);
const fuentes = Array.isArray(out.fuentes) ? out.fuentes : [];

if (accion === 'responder' && !(confianza >= 0.7)) { problemas.push('baja_confianza'); accion = 'derivar_ventas'; }
if (accion === 'responder' && fuentes.length === 0) { problemas.push('sin_fuentes'); accion = 'derivar_ventas'; }
if (ctx.estado_credito === 'Bloqueado' && ['pedido', 'credito_pago'].includes(out.categoria) && accion === 'responder') {
  problemas.push('cliente_bloqueado'); accion = 'derivar_ventas';
}
const critico = /(intoxic|enferm|mal olor|hediond|podrid|vomit|diarrea|seremi|fiscaliz)/i.test(ctx.mensaje);
if (critico && accion !== 'escalar_calidad') { problemas.push('palabra_critica'); accion = 'escalar_calidad'; }

const saludo = ctx.nombre ? `Estimado/a ${ctx.nombre}:` : 'Estimado/a cliente:';
const firma = '\n\nEquipo de atención — Carnes Los Andes';
const ACUSE = {
  derivar_ventas: `${saludo}\n\nRecibimos su consulta y la derivamos a su ejecutivo de ventas, quien le responderá dentro del día hábil.${firma}`,
  escalar_calidad: `${saludo}\n\nRecibimos su reclamo y lo escalamos al área de calidad, que lo contactará en un máximo de 2 días hábiles. Mientras tanto, le pedimos no consumir ni vender el producto y mantenerlo separado y refrigerado.${firma}`,
};
const corregida = accion !== out.accion;
const respuestaFinal = (corregida || respuesta.length < 30) && ACUSE[accion] ? ACUSE[accion] : respuesta;

return {
  json: {
    ...ctx,
    accion,
    accion_agente: out.accion ?? null,
    categoria: out.categoria ?? 'otro',
    urgencia: critico ? 'alta' : (out.urgencia ?? 'media'),
    confianza: isNaN(confianza) ? null : confianza,
    respuesta_cliente: respuestaFinal,
    resumen_interno: out.resumen_interno ?? '',
    fuentes: fuentes.join(', '),
    problemas: problemas.join(', '),
    estado: problemas.length ? 'corregida_por_validacion' : 'ok',
  },
};

// El agente falló (timeout del modelo, Vector Store caído o salida nula):
// la consulta no se pierde, se deriva a una persona con un acuse estándar.
const ctx = $('Cruzar consulta con cliente').item.json;
const saludo = ctx.nombre ? `Estimado/a ${ctx.nombre}:` : 'Estimado/a cliente:';
return {
  json: {
    ...ctx,
    accion: 'derivar_ventas',
    accion_agente: null,
    categoria: 'otro',
    urgencia: 'media',
    confianza: null,
    respuesta_cliente: `${saludo}\n\nRecibimos su consulta y un integrante del equipo le responderá dentro del día hábil.\n\nEquipo de atención — Carnes Los Andes`,
    resumen_interno: 'El agente no pudo procesar esta consulta. Revisar y responder manualmente.',
    fuentes: '',
    problemas: 'error_agente: ' + String($json.error?.message || $json.error || 'sin detalle').slice(0, 300),
    estado: 'error_agente',
  },
};

